package com.print.kiosk.service.impl;
import com.print.kiosk.entity.*;import com.print.kiosk.repository.*;import com.print.kiosk.service.interfaces.ClaimExpirationService;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class ClaimExpirationServiceImpl implements ClaimExpirationService{
    private static final ZoneId DHAKA=ZoneId.of("Asia/Dhaka"); private final RequestClaimRepository claims;private final PrintRequestRepository requests;private final PrintRequestStatusHistoryRepository history;private final long timeout;
    public ClaimExpirationServiceImpl(RequestClaimRepository c,PrintRequestRepository r,PrintRequestStatusHistoryRepository h,@Value("${app.queue.claim-timeout-minutes:30}")long timeout){claims=c;requests=r;history=h;this.timeout=timeout;}
    @Transactional public int releaseExpiredClaims(){LocalDateTime now=LocalDateTime.now(DHAKA);List<RequestClaim> due=claims.findTop100ByActiveTrueAndLastActivityAtLessThanEqualOrderByLastActivityAtAsc(now.minusMinutes(timeout));int count=0;for(RequestClaim c:due){PrintRequest r=requests.findByIdForUpdate(c.getPrintRequest().getId()).orElse(null);if(r==null||r.getStatus()==PrintRequestStatus.PRINTING||!Set.of(PrintRequestStatus.CLAIMED,PrintRequestStatus.DOWNLOADING).contains(r.getStatus()))continue;PrintRequestStatus old=r.getStatus();c.setActive(false);c.setReleasedAt(now);c.setReleaseReason(ClaimReleaseReason.AUTO_TIMEOUT);c.setReleaseNote("Claim released after "+timeout+" minutes without activity");claims.save(c);r.setStatus(PrintRequestStatus.PAID);r.setAssignedAgent(null);r.setClaimedAt(null);r.setClaimLastActivityAt(null);requests.save(r);PrintRequestStatusHistory h=new PrintRequestStatusHistory();h.setPrintRequest(r);h.setPreviousStatus(old);h.setNewStatus(PrintRequestStatus.PAID);h.setActorType(StatusActorType.SYSTEM);h.setReason(c.getReleaseNote());history.save(h);count++;}return count;}
}